using System.Buffers.Binary;
using System.Text.Json;
using System.Text.Json.Nodes;
using Stardust.Core.Protocol;
namespace Stardust.Core.SmokeTests;
public static class CreatureView6FullScenarios
{
    private static object Text(ReplicationByteString s)=>new{Hex=Convert.ToHexString(s.CopyBytes()),Extended=s.UsesExtendedLength};
    private static object Vector<T>(CreatureView6Vector<T> v)=>new{v.Counter,Values=v.Values.ToArray()};
    private static object Model(CreatureView6Baseline s)=>new{s.ObjectId,s.DeclaredCount,s.Passive,Defenders=Vector(s.Defenders),s.Level,PerformanceAnimation=Text(s.PerformanceAnimation),MoodString=Text(s.MoodString),s.WeaponId,s.GroupId,s.InviterId,s.InviteCounter,s.Guild,s.TargetId,s.MoodId,s.PerformanceStart,s.PerformanceType,Ham=Vector(s.Ham),MaximumHam=Vector(s.MaximumHam),Wearables=new{s.Wearables.Counter,Values=s.Wearables.Values.Select(w=>new{Customization=Text(w.Customization),w.Arrangement,w.ObjectId,w.TemplateCrc}).ToArray()},AlternateAppearance=Text(s.AlternateAppearance),s.Frozen};
    private static object Row(CreatureView6FullState s)=>new{Model=Model(s.Model),s.Revision,s.DecodedBytes};
    private static object Plan(CreatureView6FullDelta p)=>new{p.ObjectId,p.DeclaredCount,Updates=p.Updates.Select(u=>new{u.Index,Scalar=u.Scalar is {} s?new{s.Index,s.Bits,Text=s.Text is null?null:Text(s.Text),s.SecondId}:null,Ham=u.Ham is {} h?new{h.Field,h.Extent,h.Counter,Commands=h.Commands.Select(c=>new{c.Opcode,c.Index,Values=c.Values.ToArray()}).ToArray()}:null,Defender=u.Defender is {} d?new{d.Field,d.Extent,d.Counter,Commands=d.Commands.Select(c=>new{c.Opcode,c.Index,Values=c.Values.ToArray()}).ToArray()}:null,Wearable=u.Wearable is {} w?new{w.Field,w.Extent,w.Counter,Commands=w.Commands.Select(c=>new{c.Opcode,c.Index,Values=c.Values.Select(e=>new{Customization=Text(e.Customization),e.Arrangement,e.ObjectId,e.TemplateCrc}).ToArray()}).ToArray()}:null}).ToArray()};
    private static object Events(CreatureView6FullChange c)=>c.Events.Select(e=>new{Kind=e.Kind.ToString(),e.Field,e.UpdateOrdinal,e.Opcode,e.Index,e.OldId,e.NewId,e.OldValue,e.NewValue}).ToArray();
    public static void Run(string input,string output)
    {
        if(new FileInfo(input).Length>33554432)throw new InvalidDataException("Bounded composite fixture");using var doc=JsonDocument.Parse(File.ReadAllBytes(input));var records=new List<object>();int negatives=0,budgets=0,ownership=0;var codec=new CreatureView6FullLimits();
        void Check(bool v,string why){if(!v)throw new Exception(why);}
        void Equal(object v,JsonElement expected,string why)=>Check(JsonNode.DeepEquals(JsonSerializer.SerializeToNode(v),JsonNode.Parse(expected.GetRawText())),why);
        void Reject(Action a){negatives++;try{a();}catch(InvalidDataException){return;}catch(ArgumentException){return;}catch(OverflowException){return;}throw new Exception("Negative composite accepted");}
        foreach(var c in doc.RootElement.GetProperty("Cases").EnumerateArray())
        {
            var wire=Convert.FromHexString(c.GetProperty("Hex").GetString()!);var seedWire=Convert.FromHexString(c.GetProperty("Baseline").GetString()!);var baseline=CreatureView6Codec.DecodeBaseline(seedWire,new());var p=CreatureView6FullCodec.Decode(wire,codec);Equal(Plan(p),c.GetProperty("Plan"),"Independent ordered plan");Check(CreatureView6FullCodec.Encode(p,codec).SequenceEqual(wire),"Exact union bytes");var envelope=ReplicationEnvelopeCodec.DecodeDelta(wire,codec.MaximumPayloadBytes);Equal(Plan(CreatureView6FullCodec.Decode(envelope,codec)),c.GetProperty("Plan"),"Envelope overload");Check(CreatureView6FullCodec.EncodeEnvelope(p,codec).CopyOpaqueFields().SequenceEqual(envelope.CopyOpaqueFields()),"Exact envelope");
            var state=CreatureView6FullState.FromBaseline(baseline,new(new(MaximumElements:65536,MaximumTotalElements:262144)));Equal(Row(state),c.GetProperty("Initial"),"Full seed");string old=JsonSerializer.Serialize(Row(state));var change=state.Apply(p);Equal(Row(change.Current),c.GetProperty("Expected"),"Independent current full model");Equal(Events(change),c.GetProperty("Events"),"Ordered modern events");Check(change.WorkUsed==c.GetProperty("Work").GetInt64(),"Independent work");Check(change.DeclaredCount==65535&&change.Current.Revision==2,"Single revision/raw metadata");Check(change.DecodedOutputBytes==change.Current.DecodedBytes+48L*change.Events.Count,"Output charge");Check(JsonSerializer.Serialize(Row(state))==old,"Old state immutable");ownership++;
            var alias=(byte[])wire.Clone();var owned=CreatureView6FullCodec.Decode(alias,codec);Array.Clear(alias);Check(CreatureView6FullCodec.Encode(owned,codec).SequenceEqual(wire),"Wire ownership");ownership++;
            var list=p.Updates.ToArray();var freeze=new CreatureView6FullDelta(p.ObjectId,p.DeclaredCount,list);Array.Clear(list);Check(CreatureView6FullCodec.Encode(freeze,codec).SequenceEqual(wire),"Ordered plan ownership");ownership++;
            var mutations=new List<Action>();
            CreatureView6FullUpdate Rebuild(CreatureView6FullUpdate u)
            {
                if(u.Defender is {} d){var cs=d.Commands.Select(c=>{var v=c.Values.ToArray();var result=new CreatureDefendersView6Command(c.Opcode,c.Index,v);mutations.Add(()=>Array.Clear(v));return result;}).ToArray();var result=new CreatureView6FullUpdate(new CreatureDefendersView6Update(1,d.Extent,d.Counter,cs));mutations.Add(()=>Array.Clear(cs));return result;}
                if(u.Ham is {} h){var cs=h.Commands.Select(c=>{var v=c.Values.ToArray();var result=new CreatureHamView6Command(c.Opcode,c.Index,v);mutations.Add(()=>Array.Clear(v));return result;}).ToArray();var result=new CreatureView6FullUpdate(new CreatureHamView6Update(h.Field,h.Extent,h.Counter,cs));mutations.Add(()=>Array.Clear(cs));return result;}
                if(u.Wearable is {} w){var cs=w.Commands.Select(c=>{var v=c.Values.Select(e=>{var raw=e.Customization.CopyBytes();var text=ReplicationByteString.Create(raw,e.Customization.UsesExtendedLength);mutations.Add(()=>Array.Clear(raw));return new CreatureView6Wearable(text,e.Arrangement,e.ObjectId,e.TemplateCrc);}).ToArray();var result=new CreatureWearablesView6Command(c.Opcode,c.Index,v);mutations.Add(()=>Array.Clear(v));return result;}).ToArray();var result=new CreatureView6FullUpdate(new CreatureWearablesView6Update(w.Extent,w.Counter,cs));mutations.Add(()=>Array.Clear(cs));return result;}
                return new(u.Scalar!);
            }
            var deep=new CreatureView6FullDelta(p.ObjectId,p.DeclaredCount,p.Updates.Select(Rebuild));foreach(var mutate in mutations)mutate();Check(CreatureView6FullCodec.Encode(deep,codec).SequenceEqual(wire),"Nested command/value/string ownership");Equal(Row(state.Apply(deep).Current),c.GetProperty("Expected"),"Owned deep plan branch");ownership+=mutations.Count+1;
            var bytes=change.Current.Model.PerformanceAnimation.CopyBytes();Array.Clear(bytes);Equal(Row(change.Current),c.GetProperty("Expected"),"Inspection ownership");ownership++;
            var branch=Task.Run(()=>state.Apply(p)).GetAwaiter().GetResult();Equal(Row(branch.Current),c.GetProperty("Expected"),"Immutable concurrent branch");ownership++;
            var cc=c.GetProperty("CodecCost");int CN(string k)=>cc.GetProperty(k).GetInt32();long CL(string k)=>cc.GetProperty(k).GetInt64();var exact=new CreatureView6FullLimits(CN("Payload"),CN("Fields"),CN("MaxString"),CN("Strings"),CN("Commands"),CN("Elements"),CL("Decoded"),CL("Work"));_=CreatureView6FullCodec.Decode(wire,exact);Check(CreatureView6FullCodec.Encode(p,exact).SequenceEqual(wire),"Exact global codec caps");budgets+=2;
            var less=new List<CreatureView6FullLimits>{exact with{MaximumPayloadBytes=exact.MaximumPayloadBytes-1},exact with{MaximumFields=exact.MaximumFields-1},exact with{MaximumDecodedBytes=exact.MaximumDecodedBytes-1},exact with{MaximumWork=exact.MaximumWork-1}};if(exact.MaximumStringBytes>0)less.Add(exact with{MaximumStringBytes=exact.MaximumStringBytes-1});if(exact.MaximumTotalStringBytes>0)less.Add(exact with{MaximumTotalStringBytes=exact.MaximumTotalStringBytes-1});if(exact.MaximumCommands>0)less.Add(exact with{MaximumCommands=exact.MaximumCommands-1});if(exact.MaximumElements>0)less.Add(exact with{MaximumElements=exact.MaximumElements-1});foreach(var l in less){Reject(()=>CreatureView6FullCodec.Decode(wire,l));Reject(()=>CreatureView6FullCodec.Encode(p,l));budgets+=2;}
            var sc=c.GetProperty("StateCost");int SN(string k)=>sc.GetProperty(k).GetInt32();long SL(string k)=>sc.GetProperty(k).GetInt64();var sm=new CreatureView6StateLimits(SN("Updates"),SN("MaxString"),SN("Strings"),SN("Elements"),SN("TotalElements"),SL("StateBytes"),SN("Events"),SL("OutputBytes"),SL("Work"));var limited=state.Apply(p,new(sm,exact));Equal(Row(limited.Current),c.GetProperty("Expected"),"Exact full intermediate caps");budgets++;
            var sless=new List<CreatureView6StateLimits>{sm with{MaximumUpdates=sm.MaximumUpdates-1},sm with{MaximumStringBytes=sm.MaximumStringBytes-1},sm with{MaximumTotalStringBytes=sm.MaximumTotalStringBytes-1},sm with{MaximumElements=sm.MaximumElements-1},sm with{MaximumTotalElements=sm.MaximumTotalElements-1},sm with{MaximumStateBytes=sm.MaximumStateBytes-1},sm with{MaximumOutputBytes=sm.MaximumOutputBytes-1},sm with{MaximumWork=sm.MaximumWork-1}};if(sm.MaximumEvents>0)sless.Add(sm with{MaximumEvents=sm.MaximumEvents-1});foreach(var l in sless){Reject(()=>state.Apply(p,new(l,exact)));Check(JsonSerializer.Serialize(Row(state))==old,"Failed apply preserves old full model");budgets++;}
            foreach(var l in less){Reject(()=>state.Apply(p,new(sm,l)));budgets++;}
            var reseed=change.Current.Reseed(baseline);Equal(Row(reseed),c.GetProperty("Reseed"),"Reseed full current model");Reject(()=>state.Apply(new(p.ObjectId+1,p.DeclaredCount,p.Updates)));var wrong=(byte[])seedWire.Clone();BinaryPrimitives.WriteUInt64LittleEndian(wrong.AsSpan(6),p.ObjectId+1);Reject(()=>state.Reseed(CreatureView6Codec.DecodeBaseline(wrong,new())));Reject(()=>CreatureView6FullState.FromBaseline(baseline,null,ulong.MaxValue));var end=CreatureView6FullState.FromBaseline(baseline,null,ulong.MaxValue-1);Reject(()=>end.Apply(p));Reject(()=>end.Reseed(baseline));
            var validPrefixes=c.GetProperty("ValidPrefixes").EnumerateArray().Select(v=>v.GetInt32()).ToHashSet();for(int n=0;n<wire.Length;n++){var truncated=wire[..n];Reject(()=>CreatureView6FullCodec.Decode(truncated,codec));if(n>=25){BinaryPrimitives.WriteUInt32LittleEndian(truncated.AsSpan(19),(uint)(n-23));try{var partial=CreatureView6FullCodec.Decode(truncated,codec);Check(validPrefixes.Contains(n),"Independent prefix accepted set");Check(CreatureView6FullCodec.Encode(partial,codec).SequenceEqual(truncated),"Complete adjusted prefix exact");}catch(InvalidDataException){Check(!validPrefixes.Contains(n),"Independent complete prefix rejected");negatives++;}}}
            string kept=JsonSerializer.Serialize(Row(change.Current));Reject(()=>change.Current.Apply(p,new(sm with{MaximumWork=0},exact)));Check(JsonSerializer.Serialize(Row(change.Current))==kept,"Earlier publication survives later failure");ownership++;
            records.Add(new{Name=c.GetProperty("Name").GetString(),Plan=Plan(p),Initial=Row(state),Expected=Row(change.Current),Events=Events(change),Work=change.WorkUsed,Reseed=Row(reseed)});
        }
        foreach(var m in doc.RootElement.GetProperty("Malformed").EnumerateArray())Reject(()=>CreatureView6FullCodec.Decode(Convert.FromHexString(m.GetString()!),codec));
        Reject(()=>CreatureView6FullCodec.Encode(new(1,0,[]),codec));Reject(()=>new CreatureView6FullUpdate((CreatureView6Update)null!));Reject(()=>new CreatureView6FullUpdate((CreatureHamView6Update)null!));Reject(()=>CreatureView6FullCodec.Encode(new(1,0,[new(new CreatureHamView6Update(13,0,0,[new(4,0,[])]))]),codec));
        File.WriteAllText(output,JsonSerializer.Serialize(new{Records=records,Negatives=negatives,Budgets=budgets,Ownership=ownership},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS full CREO6 {records.Count} exact cases, {negatives} negatives, {budgets} budgets, {ownership} ownership checks");
    }
}
